    const animation = entityData.animation;
    if (animation.isCrouching !== undefined) state.isCrouching = !!animation.isCrouching;
    if (animation.isFallFlying !== undefined) state.isFallFlying = !!animation.isFallFlying;
    if (animation.swimAmount !== undefined) state.swimAmount = Number(animation.swimAmount) || 0;
    if (animation.speedValue !== undefined) state.speedValue = Math.max(1, Number(animation.speedValue) || 1);
    if (animation.attackTime !== undefined) state.attackTime = Number(animation.attackTime) || 0;
    if (animation.tentacleAngle !== undefined) state.tentacleAngle = Number(animation.tentacleAngle) || 0;
    if (animation.squidXBodyRot !== undefined) state.squidXBodyRot = Number(animation.squidXBodyRot) || 0;
    if (animation.squidZBodyRot !== undefined) state.squidZBodyRot = Number(animation.squidZBodyRot) || 0;
