    const deltaTicks = Math.max((deltaSeconds || 0) * 20, 0);
    const positionNow = rootPosition ? rootPosition.clone() : new THREE.Vector3();
    const previous = state.previousPosition ? state.previousPosition.clone() : positionNow.clone();
    const dx = positionNow.x - previous.x;
    const dy = positionNow.y - previous.y;
    const dz = positionNow.z - previous.z;
    const includeVertical = state.entityType === "glow_squid" || state.entityType === "squid";
    const walkDistance = Math.sqrt(dx * dx + dz * dz + (includeVertical ? dy * dy : 0));
    const normalizedWalkDistance = deltaTicks > 0.00001 ? walkDistance / deltaTicks : walkDistance;
    const targetWalkSpeed = Math.min(normalizedWalkDistance * 4, 1);
    const walkBlend = deltaTicks > 0 ? 1 - Math.pow(0.6, deltaTicks) : 0;
