    const bracketIndex = stateText.indexOf("[");
    const id = bracketIndex === -1 ? stateText : stateText.slice(0, bracketIndex);
    const simpleId = id.replace(/^minecraft:/, "");
    const properties = {};
    if (bracketIndex !== -1 && stateText.endsWith("]")) {
      const body = stateText.slice(bracketIndex + 1, -1);
      if (body) {
        body.split(",").forEach(function (entry) {
          const eq = entry.indexOf("=");
          if (eq === -1) {
            return;
          }
          const key = entry.slice(0, eq).trim();
          const value = entry.slice(eq + 1).trim();
          properties[key] = value;
        });
      }
    }
    return {
      name: simpleId,
      properties: properties
    };
