  function buildVanillaMooshroomModel(primary, secondary, accent) {
    const root = buildVanillaCowBaseModel("mooshroom_red");
    const parts = root.userData && root.userData.parts ? root.userData.parts : {};
    const mushroomState = "minecraft:red_mushroom[age=0]";
    const backMushroomY = 0.35;
    const headBaseY = (24 - 4) / 16;
    const headMushroomLocalY = 0.7;
    const alignedMushroomPlaneY = (backMushroomY + backMushroomY + headBaseY + headMushroomLocalY) / 3 + 1;
    const shiftedMushroomPlaneY = alignedMushroomPlaneY - 2 / 16;
    const mushroomScale = new THREE.Vector3(-1, 1, 1);

    root.updateMatrixWorld(true);

    if (parts.body) {
      const backLeft = createStaticBlockMeshFromState(mushroomState);
      bindWorldAnchoredMeshToPart(
        parts.body,
        backLeft,
        new THREE.Vector3(0.2, shiftedMushroomPlaneY, 0.5),
        toRadians(-48),
        mushroomScale
      );

      const backRight = createStaticBlockMeshFromState(mushroomState);
      const backRightOffset = new THREE.Vector3(0.1, 0, -0.6).applyAxisAngle(Y_AXIS, toRadians(42));
      bindWorldAnchoredMeshToPart(
        parts.body,
        backRight,
        new THREE.Vector3(0.2, shiftedMushroomPlaneY, 0.5).add(backRightOffset),
        toRadians(-6),
        mushroomScale
      );
    }

    if (parts.head) {
      const headMushroom = createStaticBlockMeshFromState(mushroomState);
      bindWorldAnchoredMeshToPart(
        parts.head,
        headMushroom,
        new THREE.Vector3(0, shiftedMushroomPlaneY, -0.2),
        toRadians(-78),
        mushroomScale
      );
    }

    return root;
  }

